    HelpArticle(translate("Календарь",language),listOf(periodNoteKeys[23],"Все данные","Замеры","Перейти к месяцу").joinToString("\n"){translate(it,language)}),
    HelpArticle(translate("Папки заметок",language),listOf("Создать папку","Переместить","Без папки","Все без учёта папок","Все типы","Карточки","Компактный список","Сетка",periodNoteKeys[36],"Штампы времени","Время создания заметок","Время изменения заметок","Время создания папок","Время изменения папок").joinToString("\n"){translate(it,language)}))
